/* Modern Minimal Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Modern Minimal Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 300 50% 100%;
    --foreground: 0 0% 19.89%;
    --card: 300 50% 100%;
    --card-foreground: 0 0% 19.89%;
    --popover: 300 50% 100%;
    --popover-foreground: 0 0% 19.89%;
    --primary: 217.19 91.36% 59.41%;
    --primary-foreground: 300 50% 100%;
    --secondary: 300 0% 96.06%;
    --secondary-foreground: 214.99 15.5% 34.68%;
    --muted: 300 0% 97.37%;
    --muted-foreground: 219.97 7.71% 45.75%;
    --accent: 203.98 99.97% 93.54%;
    --accent-foreground: 224.53 64.95% 33.15%;
    --destructive: 359.91 86.11% 60.55%;
    --destructive-foreground: 300 50% 100%;
    --border: 220.01 24.1% 91.61%;
    --input: 220.01 24.1% 91.61%;
    --ring: 217.19 91.36% 59.41%;
    --chart-1: 217.19 91.36% 59.41%;
    --chart-2: 221.24 86.4% 53.91%;
    --chart-3: 224.36 76.88% 48.37%;
    --chart-4: 225.99 71.15% 39.65%;
    --chart-5: 224.53 64.95% 33.15%;
    --radius: 0.375rem;
    --sidebar: 300 0% 97.37%;
    --sidebar-foreground: 0 0% 19.89%;
    --sidebar-primary: 217.19 91.36% 59.41%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 203.98 99.97% 93.54%;
    --sidebar-accent-foreground: 224.53 64.95% 33.15%;
    --sidebar-border: 220.01 24.1% 91.61%;
    --sidebar-ring: 217.19 91.36% 59.41%;
    --font-sans: Inter, sans-serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: JetBrains Mono, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 0 0% 8.61%;
    --foreground: 0 0% 89.56%;
    --card: 300 0% 15.03%;
    --card-foreground: 0 0% 89.56%;
    --popover: 300 0% 15.03%;
    --popover-foreground: 0 0% 89.56%;
    --primary: 217.19 91.36% 59.41%;
    --primary-foreground: 300 50% 100%;
    --secondary: 300 0% 15.03%;
    --secondary-foreground: 0 0% 89.56%;
    --muted: 300 0% 15.03%;
    --muted-foreground: 300 0% 64.47%;
    --accent: 224.53 64.95% 33.15%;
    --accent-foreground: 213.33 99.96% 87.05%;
    --destructive: 359.91 86.11% 60.55%;
    --destructive-foreground: 300 50% 100%;
    --border: 0 0% 24.94%;
    --input: 0 0% 24.94%;
    --ring: 217.19 91.36% 59.41%;
    --chart-1: 213.14 90.06% 67.35%;
    --chart-2: 217.19 91.36% 59.41%;
    --chart-3: 221.24 86.4% 53.91%;
    --chart-4: 224.36 76.88% 48.37%;
    --chart-5: 225.99 71.15% 39.65%;
    --radius: 0.375rem;
    --sidebar: 0 0% 8.61%;
    --sidebar-foreground: 0 0% 89.56%;
    --sidebar-primary: 217.19 91.36% 59.41%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 224.53 64.95% 33.15%;
    --sidebar-accent-foreground: 213.33 99.96% 87.05%;
    --sidebar-border: 0 0% 24.94%;
    --sidebar-ring: 217.19 91.36% 59.41%;
    --font-sans: Inter, sans-serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: JetBrains Mono, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  }

}
